<?php
namespace App\Http\Controllers;use App\Models\TerminationType;use Illuminate\Http\Request;
class TerminationTypeController extends Controller{public function index(Request $r){$q=TerminationType::latest();$q->when($r->search,fn($q,$v)=>$q->where('name','like',"%$v%"));return view('termination-types.index',['types'=>$q->paginate(10)->withQueryString()]);}public function store(Request $r){TerminationType::create($this->data($r));return back()->with('success','Termination type created.');}public function update(Request $r,TerminationType $terminationType){$terminationType->update($this->data($r,$terminationType->id));return back()->with('success','Termination type updated.');}public function toggle(TerminationType $terminationType){$terminationType->update(['status'=>!$terminationType->status]);return back()->with('success','Status updated.');}public function destroy(TerminationType $terminationType){if($terminationType->terminations()->exists())return back()->with('error','This type is used by a termination and cannot be deleted.');$terminationType->delete();return back()->with('success','Termination type deleted.');}private function data(Request $r,$id=null){$d=$r->validate(['name'=>'required|string|max:100|unique:termination_types,name,'.($id?:'NULL').',id','description'=>'nullable|string|max:500','status'=>'required|boolean']);return $d;}}
